WITH filtered AS (SELECT *, DATEDIFF(CURRENT_DATE(), paid_at) days_since_paid_at, COALESCE(method, 'NONE') method_filled FROM payments WHERE order_id IS NOT NULL AND method IN ('promptpay', 'card', 'cash')), enriched AS (SELECT a.*, o.shipping_fee, o.status AS order_status, o.channel FROM filtered a INNER JOIN orders o ON a.order_id = o.id WHERE o.store_id = 37), cleaned AS (SELECT *, CASE WHEN status = 'SUCCESS' THEN 1 ELSE 0 END is_success, COALESCE(channel, 'NONE') resolved_channel FROM enriched WHERE order_id IS NOT NULL AND amount > 1360), joined AS (SELECT a.id, a.order_id, a.method, a.amount, a.days_since_paid_at, a.method_filled, a.order_status, a.channel, a.is_success, a.resolved_channel, b.shipping_fee AS order_shipping_fee FROM cleaned a LEFT JOIN orders b ON a.order_id = b.id), with_windows AS (SELECT id, method, method_filled, order_status, LAG(is_success) OVER (PARTITION BY order_status, method ORDER BY amount, id) prev_is_success, LEAD(is_success) OVER (PARTITION BY order_status, method ORDER BY amount, id) next_is_success, LEAD(order_shipping_fee) OVER (PARTITION BY order_status, method ORDER BY amount, id) next_order_shipping_fee, ROW_NUMBER() OVER (PARTITION BY order_status, method ORDER BY amount, id) event_seq FROM joined) SELECT order_status, SORT_ARRAY(COLLECT_SET(order_status)) AS order_status_list, APPROX_PERCENTILE(next_order_shipping_fee, ARRAY(0.25, 0.5, 0.75)) AS next_order_shipping_fee_quartiles FROM with_windows GROUP BY ROLLUP (order_status) ORDER BY order_status NULLS FIRST
